with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'نظم المعلومات الجغرافية والتحليل المكاني للأرصاد','أنظمة الإحداثيات والبيانات النقطية والمتجهة والاستيفاء المكاني وتحليل التضاريس والخرائط الجوية وخدمات الخرائط.',38,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'أساسيات GIS والبيانات المكانية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التحليل المكاني والخرائط الجوية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('gis-coordinate-reference-systems','أنظمة الإحداثيات والمراجع الجغرافية','اختيار الإسقاط والمرجع المكاني للبيانات الجوية.','{"blocks":[{"type":"text","text":"يتناول الدرس أنظمة الإحداثيات والمراجع الجغرافية ضمن استخدام نظم المعلومات الجغرافية في تحليل البيانات الجوية والمناخية."},{"type":"text","text":"المفهوم الأساس: اختيار الإسقاط والمرجع المكاني للبيانات الجوية.، مع مراعاة دقة البيانات ومقياس التحليل والمرجع المكاني."},{"type":"text","text":"تبدأ العملية بتحديد السؤال المكاني والطبقات المطلوبة والفترة الزمنية ومصدر كل طبقة."},{"type":"text","text":"تراجع أنظمة الإحداثيات والإسقاطات والوحدات والمدى المكاني قبل تنفيذ التحليل."},{"type":"text","text":"تفحص جودة البيانات واكتمالها والدقة المكانية وأعلام الجودة والبيانات الوصفية."},{"type":"text","text":"تختار أداة التحليل المناسبة وفق نوع البيانات: نقطية أو متجهة أو شبكية أو زمنية."},{"type":"text","text":"تراعى حدود الاستيفاء والتعميم المكاني، ولا تفسر القيم المحسوبة كقياسات مباشرة."},{"type":"text","text":"تدمج النتائج مع محطات الرصد أو المنتجات الفضائية أو النماذج للتحقق من الاتساق."},{"type":"text","text":"تعرض الخريطة بعنوان ووحدة ومفتاح ومقياس ومصدر وتاريخ تحديث واضح."},{"type":"text","text":"تحفظ خطوات المعالجة ومعلماتها ونسخ البيانات لتكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة توزيع مطري تتضمن مواقع المحطات والسطح المستوفى وحدود الثقة ومناطق نقص الرصد."},{"type":"callout","text":"الخلاصة: التحليل المكاني الجيد يبدأ بسؤال واضح وبيانات متوافقة وينتهي بخريطة قابلة للتفسير والتدقيق."}]}',3960,55,'["تحديد الطبقات والمرجع المكاني الصحيح","تنفيذ التحليل المكاني الملائم","إخراج خريطة موثقة قابلة للتفسير"]','أساسيات GIS والبيانات المكانية'),
('gis-raster-vector-meteorology','البيانات النقطية والمتجهة في الأرصاد','تمثيل المحطات والحدود والحقول الشبكية.','{"blocks":[{"type":"text","text":"يتناول الدرس البيانات النقطية والمتجهة في الأرصاد ضمن استخدام نظم المعلومات الجغرافية في تحليل البيانات الجوية والمناخية."},{"type":"text","text":"المفهوم الأساس: تمثيل المحطات والحدود والحقول الشبكية.، مع مراعاة دقة البيانات ومقياس التحليل والمرجع المكاني."},{"type":"text","text":"تبدأ العملية بتحديد السؤال المكاني والطبقات المطلوبة والفترة الزمنية ومصدر كل طبقة."},{"type":"text","text":"تراجع أنظمة الإحداثيات والإسقاطات والوحدات والمدى المكاني قبل تنفيذ التحليل."},{"type":"text","text":"تفحص جودة البيانات واكتمالها والدقة المكانية وأعلام الجودة والبيانات الوصفية."},{"type":"text","text":"تختار أداة التحليل المناسبة وفق نوع البيانات: نقطية أو متجهة أو شبكية أو زمنية."},{"type":"text","text":"تراعى حدود الاستيفاء والتعميم المكاني، ولا تفسر القيم المحسوبة كقياسات مباشرة."},{"type":"text","text":"تدمج النتائج مع محطات الرصد أو المنتجات الفضائية أو النماذج للتحقق من الاتساق."},{"type":"text","text":"تعرض الخريطة بعنوان ووحدة ومفتاح ومقياس ومصدر وتاريخ تحديث واضح."},{"type":"text","text":"تحفظ خطوات المعالجة ومعلماتها ونسخ البيانات لتكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة توزيع مطري تتضمن مواقع المحطات والسطح المستوفى وحدود الثقة ومناطق نقص الرصد."},{"type":"callout","text":"الخلاصة: التحليل المكاني الجيد يبدأ بسؤال واضح وبيانات متوافقة وينتهي بخريطة قابلة للتفسير والتدقيق."}]}',3970,55,'["تحديد الطبقات والمرجع المكاني الصحيح","تنفيذ التحليل المكاني الملائم","إخراج خريطة موثقة قابلة للتفسير"]','أساسيات GIS والبيانات المكانية'),
('gis-meteorological-grid-management','إدارة الشبكات والحقول الجوية داخل GIS','إدخال الشبكات وتوحيد الدقة والامتداد المكاني.','{"blocks":[{"type":"text","text":"يتناول الدرس إدارة الشبكات والحقول الجوية داخل GIS ضمن استخدام نظم المعلومات الجغرافية في تحليل البيانات الجوية والمناخية."},{"type":"text","text":"المفهوم الأساس: إدخال الشبكات وتوحيد الدقة والامتداد المكاني.، مع مراعاة دقة البيانات ومقياس التحليل والمرجع المكاني."},{"type":"text","text":"تبدأ العملية بتحديد السؤال المكاني والطبقات المطلوبة والفترة الزمنية ومصدر كل طبقة."},{"type":"text","text":"تراجع أنظمة الإحداثيات والإسقاطات والوحدات والمدى المكاني قبل تنفيذ التحليل."},{"type":"text","text":"تفحص جودة البيانات واكتمالها والدقة المكانية وأعلام الجودة والبيانات الوصفية."},{"type":"text","text":"تختار أداة التحليل المناسبة وفق نوع البيانات: نقطية أو متجهة أو شبكية أو زمنية."},{"type":"text","text":"تراعى حدود الاستيفاء والتعميم المكاني، ولا تفسر القيم المحسوبة كقياسات مباشرة."},{"type":"text","text":"تدمج النتائج مع محطات الرصد أو المنتجات الفضائية أو النماذج للتحقق من الاتساق."},{"type":"text","text":"تعرض الخريطة بعنوان ووحدة ومفتاح ومقياس ومصدر وتاريخ تحديث واضح."},{"type":"text","text":"تحفظ خطوات المعالجة ومعلماتها ونسخ البيانات لتكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة توزيع مطري تتضمن مواقع المحطات والسطح المستوفى وحدود الثقة ومناطق نقص الرصد."},{"type":"callout","text":"الخلاصة: التحليل المكاني الجيد يبدأ بسؤال واضح وبيانات متوافقة وينتهي بخريطة قابلة للتفسير والتدقيق."}]}',3980,55,'["تحديد الطبقات والمرجع المكاني الصحيح","تنفيذ التحليل المكاني الملائم","إخراج خريطة موثقة قابلة للتفسير"]','أساسيات GIS والبيانات المكانية'),
