('gis-elevation-and-terrain-analysis','تحليل الارتفاعات والتضاريس للظواهر الجوية','نماذج الارتفاع والانحدار والتعرض والظل المطري.','{"blocks":[{"type":"text","text":"يتناول الدرس تحليل الارتفاعات والتضاريس للظواهر الجوية ضمن استخدام نظم المعلومات الجغرافية في تحليل البيانات الجوية والمناخية."},{"type":"text","text":"المفهوم الأساس: نماذج الارتفاع والانحدار والتعرض والظل المطري.، مع مراعاة دقة البيانات ومقياس التحليل والمرجع المكاني."},{"type":"text","text":"تبدأ العملية بتحديد السؤال المكاني والطبقات المطلوبة والفترة الزمنية ومصدر كل طبقة."},{"type":"text","text":"تراجع أنظمة الإحداثيات والإسقاطات والوحدات والمدى المكاني قبل تنفيذ التحليل."},{"type":"text","text":"تفحص جودة البيانات واكتمالها والدقة المكانية وأعلام الجودة والبيانات الوصفية."},{"type":"text","text":"تختار أداة التحليل المناسبة وفق نوع البيانات: نقطية أو متجهة أو شبكية أو زمنية."},{"type":"text","text":"تراعى حدود الاستيفاء والتعميم المكاني، ولا تفسر القيم المحسوبة كقياسات مباشرة."},{"type":"text","text":"تدمج النتائج مع محطات الرصد أو المنتجات الفضائية أو النماذج للتحقق من الاتساق."},{"type":"text","text":"تعرض الخريطة بعنوان ووحدة ومفتاح ومقياس ومصدر وتاريخ تحديث واضح."},{"type":"text","text":"تحفظ خطوات المعالجة ومعلماتها ونسخ البيانات لتكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة توزيع مطري تتضمن مواقع المحطات والسطح المستوفى وحدود الثقة ومناطق نقص الرصد."},{"type":"callout","text":"الخلاصة: التحليل المكاني الجيد يبدأ بسؤال واضح وبيانات متوافقة وينتهي بخريطة قابلة للتفسير والتدقيق."}]}',4000,55,'["تحديد الطبقات والمرجع المكاني الصحيح","تنفيذ التحليل المكاني الملائم","إخراج خريطة موثقة قابلة للتفسير"]','أساسيات GIS والبيانات المكانية'),
('gis-station-buffer-and-coverage','تحليل تغطية المحطات ونطاقات الخدمة','المسافات ومناطق التأثير وفجوات الرصد.','{"blocks":[{"type":"text","text":"يتناول الدرس تحليل تغطية المحطات ونطاقات الخدمة ضمن استخدام نظم المعلومات الجغرافية في تحليل البيانات الجوية والمناخية."},{"type":"text","text":"المفهوم الأساس: المسافات ومناطق التأثير وفجوات الرصد.، مع مراعاة دقة البيانات ومقياس التحليل والمرجع المكاني."},{"type":"text","text":"تبدأ العملية بتحديد السؤال المكاني والطبقات المطلوبة والفترة الزمنية ومصدر كل طبقة."},{"type":"text","text":"تراجع أنظمة الإحداثيات والإسقاطات والوحدات والمدى المكاني قبل تنفيذ التحليل."},{"type":"text","text":"تفحص جودة البيانات واكتمالها والدقة المكانية وأعلام الجودة والبيانات الوصفية."},{"type":"text","text":"تختار أداة التحليل المناسبة وفق نوع البيانات: نقطية أو متجهة أو شبكية أو زمنية."},{"type":"text","text":"تراعى حدود الاستيفاء والتعميم المكاني، ولا تفسر القيم المحسوبة كقياسات مباشرة."},{"type":"text","text":"تدمج النتائج مع محطات الرصد أو المنتجات الفضائية أو النماذج للتحقق من الاتساق."},{"type":"text","text":"تعرض الخريطة بعنوان ووحدة ومفتاح ومقياس ومصدر وتاريخ تحديث واضح."},{"type":"text","text":"تحفظ خطوات المعالجة ومعلماتها ونسخ البيانات لتكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة توزيع مطري تتضمن مواقع المحطات والسطح المستوفى وحدود الثقة ومناطق نقص الرصد."},{"type":"callout","text":"الخلاصة: التحليل المكاني الجيد يبدأ بسؤال واضح وبيانات متوافقة وينتهي بخريطة قابلة للتفسير والتدقيق."}]}',4010,55,'["تحديد الطبقات والمرجع المكاني الصحيح","تنفيذ التحليل المكاني الملائم","إخراج خريطة موثقة قابلة للتفسير"]','أساسيات GIS والبيانات المكانية'),
('gis-spatiotemporal-weather-data','تحليل البيانات الجوية المكانية والزمنية','ربط الموقع والوقت والحدث في طبقة تحليلية.','{"blocks":[{"type":"text","text":"يتناول الدرس تحليل البيانات الجوية المكانية والزمنية ضمن استخدام نظم المعلومات الجغرافية في تحليل البيانات الجوية والمناخية."},{"type":"text","text":"المفهوم الأساس: ربط الموقع والوقت والحدث في طبقة تحليلية.، مع مراعاة دقة البيانات ومقياس التحليل والمرجع المكاني."},{"type":"text","text":"تبدأ العملية بتحديد السؤال المكاني والطبقات المطلوبة والفترة الزمنية ومصدر كل طبقة."},{"type":"text","text":"تراجع أنظمة الإحداثيات والإسقاطات والوحدات والمدى المكاني قبل تنفيذ التحليل."},{"type":"text","text":"تفحص جودة البيانات واكتمالها والدقة المكانية وأعلام الجودة والبيانات الوصفية."},{"type":"text","text":"تختار أداة التحليل المناسبة وفق نوع البيانات: نقطية أو متجهة أو شبكية أو زمنية."},{"type":"text","text":"تراعى حدود الاستيفاء والتعميم المكاني، ولا تفسر القيم المحسوبة كقياسات مباشرة."},{"type":"text","text":"تدمج النتائج مع محطات الرصد أو المنتجات الفضائية أو النماذج للتحقق من الاتساق."},{"type":"text","text":"تعرض الخريطة بعنوان ووحدة ومفتاح ومقياس ومصدر وتاريخ تحديث واضح."},{"type":"text","text":"تحفظ خطوات المعالجة ومعلماتها ونسخ البيانات لتكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة توزيع مطري تتضمن مواقع المحطات والسطح المستوفى وحدود الثقة ومناطق نقص الرصد."},{"type":"callout","text":"الخلاصة: التحليل المكاني الجيد يبدأ بسؤال واضح وبيانات متوافقة وينتهي بخريطة قابلة للتفسير والتدقيق."}]}',4020,55,'["تحديد الطبقات والمرجع المكاني الصحيح","تنفيذ التحليل المكاني الملائم","إخراج خريطة موثقة قابلة للتفسير"]','أساسيات GIS والبيانات المكانية'),
