('gis-national-meteorological-atlas','بناء أطلس جغرافي للأرصاد والمناخ','تجميع الطبقات والمؤشرات والخرائط المرجعية.','{"blocks":[{"type":"text","text":"يتناول الدرس بناء أطلس جغرافي للأرصاد والمناخ ضمن استخدام نظم المعلومات الجغرافية في تحليل البيانات الجوية والمناخية."},{"type":"text","text":"المفهوم الأساس: تجميع الطبقات والمؤشرات والخرائط المرجعية.، مع مراعاة دقة البيانات ومقياس التحليل والمرجع المكاني."},{"type":"text","text":"تبدأ العملية بتحديد السؤال المكاني والطبقات المطلوبة والفترة الزمنية ومصدر كل طبقة."},{"type":"text","text":"تراجع أنظمة الإحداثيات والإسقاطات والوحدات والمدى المكاني قبل تنفيذ التحليل."},{"type":"text","text":"تفحص جودة البيانات واكتمالها والدقة المكانية وأعلام الجودة والبيانات الوصفية."},{"type":"text","text":"تختار أداة التحليل المناسبة وفق نوع البيانات: نقطية أو متجهة أو شبكية أو زمنية."},{"type":"text","text":"تراعى حدود الاستيفاء والتعميم المكاني، ولا تفسر القيم المحسوبة كقياسات مباشرة."},{"type":"text","text":"تدمج النتائج مع محطات الرصد أو المنتجات الفضائية أو النماذج للتحقق من الاتساق."},{"type":"text","text":"تعرض الخريطة بعنوان ووحدة ومفتاح ومقياس ومصدر وتاريخ تحديث واضح."},{"type":"text","text":"تحفظ خطوات المعالجة ومعلماتها ونسخ البيانات لتكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة توزيع مطري تتضمن مواقع المحطات والسطح المستوفى وحدود الثقة ومناطق نقص الرصد."},{"type":"callout","text":"الخلاصة: التحليل المكاني الجيد يبدأ بسؤال واضح وبيانات متوافقة وينتهي بخريطة قابلة للتفسير والتدقيق."}]}',4150,55,'["تحديد الطبقات والمرجع المكاني الصحيح","تنفيذ التحليل المكاني الملائم","إخراج خريطة موثقة قابلة للتفسير"]','التحليل المكاني والخرائط الجوية'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'أساسيات GIS والبيانات المكانية' then u1.id else u2.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'نظم المعلومات الجغرافية والتحليل المكاني للأرصاد',d.unit from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;